// A single large write is handed to the HTTP/2 session as one queued chunk.
// If the client cancels the stream while that chunk is still queued, the
// session is left unable to serve any of the requests that follow it, so we
// slice the payload and stop writing as soon as the stream is gone.
function sendChunked (payload, res, reply) {
  const buffer = Buffer.isBuffer(payload) ? payload : Buffer.from(payload)
  let offset = 0

  function write () {
    while (offset < buffer.length) {
      if (res.writableEnded === true || res.stream?.destroyed === true) {
        return
      }
      const chunk = buffer.subarray(offset, offset + HTTP2_CHUNK_SIZE)
      offset += chunk.length
      if (res.write(chunk) === false && offset < buffer.length) {
        res.once('drain', write)
        return
      }
    }
    sendTrailer(payload, res, reply)
  }

  write()
}

