'use strict'

// Compares a single huge write against chunked writes on an HTTP/2 session
// when the client cancels the stream mid-flight.
const http2 = require('node:http2')

const payload = Buffer.alloc(8 * 1024 * 1024, 'a')
const mode = process.argv[2] // 'single' | 'chunked'

const server = http2.createServer((req, res) => {
  if (req.url === '/small') {
    res.writeHead(200, { 'content-length': '2' })
    res.end('ok')
    return
  }
  res.writeHead(200, { 'content-length': '' + payload.length })
  if (mode === 'single') {
    res.write(payload)
    res.end()
  } else {
    let offset = 0
    const size = 16 * 1024
    const write = () => {
      while (offset < payload.length) {
        if (res.writableEnded === true || res.stream?.destroyed === true) return
        const chunk = payload.subarray(offset, offset + size)
        offset += chunk.length
        if (res.write(chunk) === false && offset < payload.length) {
          res.once('drain', write)
          return
        }
      }
      res.end()
    }
    write()
  }
})

server.listen(0, async () => {
  const session = http2.connect(`http://localhost:${server.address().port}`)

  await new Promise((resolve) => {
    const req = session.request({ ':path': '/large' })
    req.on('data', () => req.close(http2.constants.NGHTTP2_CANCEL))
    req.on('close', resolve)
    req.on('error', resolve)
    req.end()
  })

  const result = await Promise.race([
    new Promise((resolve, reject) => {
      const req = session.request({ ':path': '/small' })
      let data = ''
      req.setEncoding('utf8')
      req.on('data', (c) => { data += c })
      req.on('end', () => resolve(data))
      req.on('error', (e) => resolve('error: ' + e.code))
      req.end()
    }),
    new Promise((resolve) => setTimeout(() => resolve('TIMEOUT'), 3000))
  ])

  console.log(mode, '-> second request:', result, 'sessionDestroyed:', session.destroyed)
  session.destroy()
  server.close()
})

