    t.assert.strictEqual(res.headers[':status'], 200)
    t.assert.strictEqual(res.headers['content-length'], '' + largePayload.length)
    t.assert.strictEqual(Buffer.byteLength(res.body), largePayload.length)
  })

  await t.test('the session survives a cancelled request', async (t) => {
    t.plan(2)

    const session = http2.connect(url)
    t.after(() => session.close())

    // cancel the request as soon as the first chunks arrive, leaving the rest
    // of the payload unwritten
    await new Promise((resolve, reject) => {
      const req = session.request({ ':path': '/large' })
      req.on('data', () => { req.close(http2.constants.NGHTTP2_CANCEL) })
      req.on('close', resolve)
      req.on('error', (err) => {
        if (err.code === 'ERR_HTTP2_STREAM_ERROR') resolve()
        else reject(err)
      })
      req.end()
    })

    // the same session must still be able to serve requests
    const body = await new Promise((resolve, reject) => {
      const req = session.request({ ':path': '/small' })
      let data = ''
      req.setEncoding('utf8')
      req.on('data', (chunk) => { data += chunk })
      req.on('end', () => resolve(data))
      req.on('error', reject)
      req.end()
    })

    t.assert.deepStrictEqual(JSON.parse(body), msg)
    t.assert.ok(!session.destroyed)
  })
})
